class CarbonSavingsChart extends StatelessWidget {
  const CarbonSavingsChart({super.key});
  @override Widget build(BuildContext context) => Container(padding: const EdgeInsets.fromLTRB(18, 16, 18, 12), decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(20)), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Carbon Savings', style: GoogleFonts.poppins(fontSize: 14, fontWeight: FontWeight.w600)), Text('Total: 23.7 kg CO2 this week', style: GoogleFonts.poppins(fontSize: 9, color: const Color(0xFF8C8C8C)))])), Container(padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 6), decoration: BoxDecoration(color: const Color(0xFFE5F4E7), borderRadius: BorderRadius.circular(14)), child: Text('+8.4 kg', style: GoogleFonts.poppins(fontSize: 9, color: const Color(0xFF2E7D32), fontWeight: FontWeight.w700)))]), const SizedBox(height: 10), const SizedBox(height: 78, child: CustomPaint(painter: _CarbonPainter()))]));
