class _CarbonPainter extends CustomPainter { const _CarbonPainter(); @override void paint(Canvas canvas, Size size) { const List<double> values = [25.0, 39.0, 32.0, 52.0, 43.0, 62.0, 49.0]; const labels = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']; for (var i = 0; i < values.length; i++) { final x = 27.0 + i * 36.5; final rect = RRect.fromRectAndRadius(Rect.fromLTWH(x, 68.0 - values[i], 20.0, values[i]), const Radius.circular(5)); canvas.drawRRect(rect, Paint()..color = i == 6 ? const Color(0xFF2E7D32) : const Color(0xFF81C784)); final text = TextPainter(text: TextSpan(text: labels[i], style: TextStyle(fontSize: 7, color: i == 6 ? const Color(0xFF2E7D32) : const Color(0xFF888888))), textDirection: TextDirection.ltr)..layout(); text.paint(canvas, Offset(x + 10.0 - text.width / 2, 70.0)); } } @override bool shouldRepaint(covariant CustomPainter oldDelegate) => false; }
